def expand_to_ri_codes(umd_cortar_no: str) -> list[str]:
    """읍/면 법정동코드(10자리) → 하위 리 법정동코드 목록.

    맵에 없으면 빈 리스트를 돌려준다 — 리 확장 대상이 아니거나(동 단위로 이미
    조회 가능) 아직 원장 생성 시점에 무매칭 목록에 없었던 읍/면이다. 호출부는
    빈 리스트를 "확장할 게 없다"로 처리하면 된다(원본 코드로 조회 시도 자체를
    건너뛰는 것도 자유 — 이미 본루프에서 0행으로 확인된 코드이므로).
    """
    ri_codes = RI_CODE_MAP.get(umd_cortar_no)
    if not ri_codes:
        return []
    prefix = umd_cortar_no[:8]
    return [prefix + ri_cd for ri_cd in ri_codes]
